/* WS2812 Test (RP2350 RISC-V, Hazard3 RV32IMAC).
 * Generated by gen_rv32.py - do not hand-edit (edit the generator).
 * Flash base 0x10000000 (entry via bootrom), SRAM to 0x20082000.
 */
    .text
    .globl _start
    .align 2
_start:
    lui sp, 0x20082            # SP = top of SRAM
    lui t0, 0x40070            # UART0 base
    addi t1, zero, 0x301
    sw t1, 0x30(t0)            # UARTEN|TXE|RXE

.Lr1: auipc a0, %pcrel_hi(.Ls1)
    addi a0, a0, %pcrel_lo(.Lr1)
    jal ra, print_string
    ws_progaddr:
    auipc t3, %pcrel_hi(.Lprogdata)
    addi t3, t3, %pcrel_lo(ws_progaddr)
    lui s0, 0x50200
    addi t4, zero, 0
    ws_copy:
    slli t5, t4, 2
    add t5, t3, t5
    lw t5, 0(t5)
    slli t6, t4, 2
    addi t6, t6, 0x48
    add t6, s0, t6
    sw t5, 0(t6)
    addi t4, t4, 1
    addi t6, zero, 8
    bltu t4, t6, ws_copy
    lui t1, 0x20004
    sw t1, 0xDC(s0)
    lui t1, 0x7
    sw t1, 0xCC(s0)
    lui t1, 0xa0
    sw t1, 0xD0(s0)
    lui t1, 0x10
    sw t1, 0xC8(s0)
    lui t1, 0xff0
    sw t1, 0x10(s0)
    addi t1, zero, 1
    sw t1, 0(s0)
    lui t2, 0x31
    addi t2, t2, -704
    ws_wait:
    lw t1, 0xD4(s0)
    addi t3, zero, 7
    beq t1, t3, ws_done
    addi t2, t2, -1
    bnez t2, ws_wait
.Lr2: auipc a0, %pcrel_hi(.Ls2)
    addi a0, a0, %pcrel_lo(.Lr2)
    jal ra, print_string
    j ws_finish
    ws_done:
.Lr3: auipc a0, %pcrel_hi(.Ls3)
    addi a0, a0, %pcrel_lo(.Lr3)
    jal ra, print_string
    ws_finish:
    lui t1, 0x2000
    lui t0, 0xD0000
    sw t1, 0x24(t0)
    sw t1, 0x14(t0)
.Lr4: auipc a0, %pcrel_hi(.Ls4)
    addi a0, a0, %pcrel_lo(.Lr4)
    jal ra, print_string

halt:
    j halt


print_string:                # a0 = ptr
    addi sp, sp, -16
    sw ra, 12(sp)
    sw t0, 8(sp)
    sw t1, 4(sp)
ps_loop:
    lbu t1, 0(a0)
    beqz t1, ps_done
    lui t0, 0x40070
    sw t1, 0(t0)
    addi a0, a0, 1
    j ps_loop
ps_done:
    lw ra, 12(sp)
    lw t0, 8(sp)
    lw t1, 4(sp)
    addi sp, sp, 16
    ret

print_hex32:                 # a0 = word: 8 hex digits + newline
    addi sp, sp, -16
    sw ra, 12(sp)
    sw t1, 8(sp)
    sw t2, 4(sp)
    addi t2, zero, 8
    mv t1, a0
hex_digit:
    srli a0, t1, 28
    slli t1, t1, 4
    addi t0, zero, 10
    bgeu a0, t0, hex_alpha
    addi a0, a0, 0x30
    j hex_out
hex_alpha:
    addi a0, a0, 0x37
hex_out:
    lui t0, 0x40070
    sw a0, 0(t0)
    addi t2, t2, -1
    bnez t2, hex_digit
    addi a0, zero, 0x0A
    lui t0, 0x40070
    sw a0, 0(t0)
    lw ra, 12(sp)
    lw t1, 8(sp)
    lw t2, 4(sp)
    addi sp, sp, 16
    ret

uart_getc:                   # -> a0 = byte (blocks)
    lui t0, 0x40070
ug_wait:
    lw t1, 0x18(t0)
    andi t1, t1, 0x10
    bnez t1, ug_wait
    lw a0, 0(t0)
    andi a0, a0, 0xFF
    ret


    .section .rodata
    .align 2
.Ls1: .asciz "WS2812 Test Starting (PIO0 SM0, side-set, pin 16)\n"
.Ls2: .asciz "WS2812 TIMEOUT waiting for SM\n"
.Ls3: .asciz "WS2812 24 bits sent (GRB=FF0000), SM idle at done loop\n"
.Ls4: .asciz "WS2812 Test Complete!\n"
.align 2
.Lprogdata: .word 0x80A0, 0xE0D7, 0x6121, 0x1125, 0x1206, 0xA142, 0x1182, 0x1007
